    for i in range(rows):
        for j in range(cols):
            # If element is negative, set it to 0
            if matrix[i][j] < 0:
                new_matrix[i][j] = 0
            # If element is 0, set it to 1
            elif matrix[i][j] == 0:
                new_matrix[i][j] = 1
            else:
                # Sum of top, bottom, left, and right neighbors
                total = 0
                if i > 0:
                    total += matrix[i-1][j]
                if i < rows - 1:
                    total += matrix[i+1][j]
                if j > 0:
