def convert_datetime(dates, times):

    format_in = "%Y-%m-%d %H:%M:%S"
    format_out = "%B %d, %Y, %H:%M:%S"
    result = []

    for date, time in zip_longest(dates, times):
        if date is None:
            date = datetime.now().date().isoformat()   # get current date if None
        if time is None:
            time = datetime.now().time().isoformat()   # get current time if None

        try:
            dt = datetime.strptime(f"{date} {time}", format_in)   # validate and convert date and time
            result.append( dt.strftime(format_out) )   # convert the date and time to the desired format
        except ValueError:
            # Exception handle for both date and time.
            # Value might be incorrect such as February 30.
            print(f"Invalid date or time: {date} {time}")
            continue

    return result

