def parse_urls(url):
    """Create a function named "parse_urls" which takes a single string parameter and returns a dictionary of queries from the URL. The URL can contain multiple query parameters separated by "&". Each query parameter is represented by a key-value pair, with the key and value separated by an equals sign ("="). The value can be URL-encoded.

The function should correctly parse the URL and return a dictionary where the keys are the query parameter names and the values are the corresponding query parameter values. If a query parameter appears multiple times in the URL, only the last occurrence should be included in the dictionary.

Additionally, the function should also handle nested query parameters. Nested query parameters are represented by using square brackets ("[]") in the key. For example, "product[name]=shirt" represents a nested query parameter where the key is "product[name]" and the value is "shirt".

For example, given the following URL:

url = "https://www.example.com/product?color=red&size=small&color=blue&product[name]=shirt"

The function should return the following dictionary:

{
    "color": "blue",
    "size": "small",
    "product": {
        "name": "shirt"
    }
}

Note that the query parameter "color" appears twice in the URL, but only the last occurrence is included in the dictionary. Additionally, the nested query parameter "product[name]" is correctly parsed and included in the dictionary."""

output:
def parse_urls(url):

    query_start = url.find("?")
    if query_start == -1:
        return {}

    query_params = url[query_start + 1:].split("&")
    result = {}

    for param in query_params:
        key_value = param.split("=")
        key = key_value[0]
        value = key_value[1] if len(key_value) > 1 else ""

        if "[" in key:
            nested_keys = key.split("[")
            nested_dict = result
            for nested_key in nested_keys[:-1]:
                if nested_key not in nested_dict:
                    nested_dict[nested_key] = {}
                nested_dict = nested_dict[nested_key]

            last_key = nested_keys[-1].replace("]", "")
            nested_dict[last_key] = value
        else:
            result[key] = value

    return result

