def clamp_number(num, min_val, max_val):

    if num < 0:
        num = abs(num)

    if num < min_val:
        if min_val - num <= 0.1 * min_val:
            return f"The number is within 10% of the minimum value: {min_val - num} away from the boundary."
        else:
            return min_val
    elif num > max_val:
        if num - max_val <= 0.1 * max_val:
            return f"The number is within 10% of the maximum value: {num - max_val} away from the boundary."
        else:
            return max_val
    else:
        return num

def generate_fibonacci(n):

    # Handle invalid inputs
    if not isinstance(n, int) or n < 1:
        return "Invalid input. Please enter a positive integer."

    # Base cases
    if n == 1:
        return [0]
    elif n == 2:
        return [0, 1]

    # Generate Fibonacci sequence
    fib_sequence = [0, 1]
    for i in range(2, n):
        fib_sequence.append(fib_sequence[i-1] + fib_sequence[i-2])

    return fib_sequence

def binary_search(arr, target):

    left = 0
    right = len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return True
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return False

