from typing import List

def countDistinctIslands(grid: List[List[int]]) -> int:

    def dfs(grid, i, j, path, direction):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == 0:
            return '0'
        grid[i][j] = 0
        path += direction
        path = dfs(grid, i+1, j, path, 'D')
        path = dfs(grid, i-1, j, path, 'U')
        path = dfs(grid, i, j+1, path, 'R')
        path = dfs(grid, i, j-1, path, 'L')
        return path + '0'

    distinct_islands = set()
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                island_shape = dfs(grid, i, j, '', 'X')
                distinct_islands.add(island_shape)
    return len(distinct_islands)

