def cost_sensitivity(matrix): 

    n = len(matrix) 
    cost_matrix = [[0 for i in range(n)] for j in range(n)] 
    cost_matrix[0][0] = matrix[0][0]  

    for i in range(1, n): 
        cost_matrix[i][0] = matrix[i][0] + cost_matrix[i-1][0] 
        cost_matrix[0][i] = matrix[0][i] + cost_matrix[0][i-1] 

    # fill the cost matrix in bottom-up fashion 
    for i in range(1, n): 
        for j in range(1, n): 
            cost_matrix[i][j] = min(cost_matrix[i-1][j], cost_matrix[i][j-1]) + matrix[i][j] 

    # cost sensitivity metric 
    cost_sensitivity_matrix = [[0 for i in range(n)] for j in range(n)] 
    for i in range(1, n): 
        for j in range(1, n): 
            cost_sensitivity_matrix[i][j] = cost_matrix[i][j] - (cost_matrix[i-1][j] + cost_matrix[i][j-1])

