def fuzzy_search(query_string):

    query_string = query_string.lower()
    results = []
    # Split query string into words
    words = query_string.split()
    for word in words:
        for char in word:
            # Replace any non-word character with a wildcard
            if not char.isalpha():
                word = word.replace(char, '.*')

            # Replace any consecutive non-word characters with a single wildcard
            word = re.sub(r'[\W]+', '.*', word)

            results.append(word)
