    sorted_ages = sorted(ages)
    if len(sorted_ages) % 2 == 0:
        median_age = (sorted_ages[len(sorted_ages) // 2] + sorted_ages[len(sorted_ages) // 2 - 1]) / 2
    else:
        median_age = sorted_ages[len(sorted_ages) // 2]

