def max_bitwise_xor(nums: List[int]) -> int:

    msb = 30
    res = 0
    while msb >= 0:
        count = 0
        for num in nums:
            if num & (1 << msb):
                count += 1
        if count >= 2:
            res |= 1 << msb
            for i in range(len(nums)):
                if nums[i] & (1 << msb):
                    nums[i] ^= res
        msb -= 1
    return res

