def reverse_string_with_punctuation(string):

    punctuation_indices = []
    alphanumeric_chars = []

    # Identify punctuation characters and alphanumeric characters
    for i, char in enumerate(string):
        if char.isalnum():
            alphanumeric_chars.append(char)
        else:
            punctuation_indices.append(i)

    # Reverse the alphanumeric characters
    reversed_string = ''.join(alphanumeric_chars[::-1])

    # Insert punctuation characters back into the reversed string
    for index in punctuation_indices:
        reversed_string = reversed_string[:index] + string[index] + reversed_string[index:]

    return reversed_string

