    # Create a dictionary of resources and their capacities
    resource_dic = {}
    for resource in resources:
        resource_dic[resource] = {
            "capacity": resources[resource]["capacity"],
            "available": resources[resource]["capacity"]
        }

    # Initialize the schedule
